## THE MEME DYNASTY IS NOT IN THE APP. A Meme Dynasty chikimon the account owns (hatched or bought on
## the website) is SET ASIDE for the session: taken out of `units`, the party and the bench so that no
## screen, fight or companion ever sees it, and PUT BACK exactly where it was every time the profile is
## saved or sent to the server — the account, its save signature and the website never lose one.
## Meme eggs are set aside the same way while no species is allowed. Hidden only after `_load` has
## verified the save, because the signature covers units and eggs.
var _meme_stash: Dictionary = {}
var _meme_ready: = false


func _meme_hide() -> void :
	if not _meme_ready or ChikFeat.on("meme_dynasty"):
		return
	var units: Dictionary = d.get("units", {})
	var hid: = {}
	for uid in units.keys():
		if typeof(units[uid]) == TYPE_DICTIONARY and Econ.app_hides(String((units[uid] as Dictionary).get("species", ""))):
			hid[String(uid)] = units[uid]
	var eggs_hid: Array = []
	if not ChikFeat.any_dynasty():
		for e in d.get("eggs", []):
			if typeof(e) == TYPE_DICTIONARY and String((e as Dictionary).get("kind", "")) == "meme":
				eggs_hid.append(e)
	if hid.is_empty() and eggs_hid.is_empty():
		return
	if _meme_stash.is_empty():
		_meme_stash = {"units": {}, "eggs": [], "party": (d.get("party", []) as Array).duplicate(), 
			"bench": (d.get("bench", []) as Array).duplicate(), "lead": int(d.get("lead", 0)), 
			"companion": (d.get("companion", {}) as Dictionary).duplicate(true), "extra": false}
	else:
		_meme_stash["extra"] = true
	var party: Array = d.get("party", [])
	var lead_uid: = ""
	if not party.is_empty():
		lead_uid = String(party[clampi(int(d.get("lead", 0)), 0, party.size() - 1)])
	for uid in hid:
		(_meme_stash["units"] as Dictionary)[uid] = hid[uid]
		units.erase(uid)
	d["party"] = party.filter(func(u): return not hid.has(String(u)))
	d["bench"] = (d.get("bench", []) as Array).filter(func(u): return not hid.has(String(u)))
	d["lead"] = maxi(0, (d["party"] as Array).find(lead_uid))
	if not eggs_hid.is_empty():
		(_meme_stash["eggs"] as Array).append_array(eggs_hid)
		d["eggs"] = (d["eggs"] as Array).filter(func(e): return not (typeof(e) == TYPE_DICTIONARY and String((e as Dictionary).get("kind", "")) == "meme"))
	_meme_stash["vis_party"] = (d["party"] as Array).duplicate()
	_meme_stash["vis_bench"] = (d["bench"] as Array).duplicate()
	_meme_stash["vis_lead"] = int(d["lead"])
	_sync_companion()


func _meme_unhide() -> void :
	if _meme_stash.is_empty():
		return
	var st: = _meme_stash
	_meme_stash = {}
	var units: Dictionary = d.get("units", {})
	var back: Dictionary = st["units"]
	for uid in back:
		units[uid] = back[uid]
	d["units"] = units
	if not bool(st["extra"]) and d.get("party", []) == st["vis_party"] and d.get("bench", []) == st["vis_bench"]\
	and int(d.get("lead", 0)) == int(st["vis_lead"]):
		d["party"] = st["party"]
		d["bench"] = st["bench"]
		d["lead"] = st["lead"]
		d["companion"] = st["companion"]
	else:
		var party: Array = (d.get("party", []) as Array).duplicate()
		var bench: Array = (d.get("bench", []) as Array).duplicate()
		var lead_uid: = ""
		if not party.is_empty():
			lead_uid = String(party[clampi(int(d.get("lead", 0)), 0, party.size() - 1)])
		var old_party: Array = st["party"]
		for i in range(old_party.size()):
			var u: = String(old_party[i])
			if back.has(u) and not party.has(u) and not bench.has(u):
				if party.size() < Econ.PARTY_MAX:
					party.insert(mini(i, party.size()), u)
				else:
					bench.append(u)
		for u in back:
			if not party.has(u) and not bench.has(u):
				bench.append(u)
		d["party"] = party
		d["bench"] = bench
		d["lead"] = maxi(0, party.find(lead_uid))
		_sync_companion()
	if not (st["eggs"] as Array).is_empty():
		eggs().append_array(st["eggs"])


func meme_stash_asset_ids() -> Array:
	var out: Array = []
	for uid in _meme_stash.get("units", {}):
		var a: = String((_meme_stash["units"][uid] as Dictionary).get("asset_id", ""))
		if a != "":
			out.append(a)
	for e in _meme_stash.get("eggs", []):
		var ea: = String((e as Dictionary).get("asset_id", ""))
		if ea != "":
			out.append(ea)
	return out


func _meme_stash_has(sp: String) -> bool:
	for uid in _meme_stash.get("units", {}):
		if String((_meme_stash["units"][uid] as Dictionary).get("species", "")) == sp:
			return true
	return false


